from typing import TypedDict
from langgraph.graph import StateGraph


class State(TypedDict):
    question: str
    category: str
    answer: str


builder = StateGraph(State)

# A node gets the full state and returns only what it changes:
def classify(state: State) -> dict:
    q = state["question"].lower()
    return {"category": "billing" if "refund" in q else "general"}

print(classify({"question": "I want a refund", "category": "", "answer": ""}))
# {'category': 'billing'}

from typing import TypedDict
from langgraph.graph import StateGraph, START, END


class State(TypedDict):
    text: str
    words: int
    shout: str


def count(state: State) -> dict:
    return {"words": len(state["text"].split())}


def upper(state: State) -> dict:
    return {"shout": state["text"].upper()}


builder = StateGraph(State)
builder.add_node(count)              # node name = "count"
builder.add_node("upper", upper)
builder.add_edge(START, "count")
builder.add_edge("count", "upper")
builder.add_edge("upper", END)

from typing import Literal
from langchain.chat_models import init_chat_model
from langchain.tools import tool
from langchain_core.messages import ToolMessage
from langgraph.graph import StateGraph, START, END, MessagesState


@tool
def multiply(a: int, b: int) -> int:
    """Multiply two integers."""
    return a * b


TOOLS = {"multiply": multiply}
model = init_chat_model("claude-sonnet-4-6").bind_tools(list(TOOLS.values()))


def call_model(state: MessagesState) -> dict:
    return {"messages": [model.invoke(state["messages"])]}


def run_tools(state: MessagesState) -> dict:
    calls = state["messages"][-1].tool_calls
    return {"messages": [ToolMessage(str(TOOLS[c["name"]].invoke(c["args"])), tool_call_id=c["id"])
                         for c in calls]}


def should_continue(state: MessagesState) -> Literal["tools", "__end__"]:
    return "tools" if state["messages"][-1].tool_calls else END


b = StateGraph(MessagesState)
b.add_node("model", call_model)
b.add_node("tools", run_tools)
b.add_edge(START, "model")
b.add_conditional_edges("model", should_continue)
b.add_edge("tools", "model")
agent = b.compile()

from langgraph.config import get_stream_writer
from langgraph.graph import StateGraph, START, END, MessagesState


def research(state: MessagesState) -> dict:
    writer = get_stream_writer()
    for pct in (25, 50, 100):
        writer({"progress": pct})                  # -> "custom" mode
    return {"messages": [{"role": "assistant", "content": "Found 3 sources"}]}


b = StateGraph(MessagesState)
b.add_node(research)
b.add_edge(START, "research")
b.add_edge("research", END)
graph = b.compile()

for part in graph.stream({"messages": [{"role": "user", "content": "bees"}]},
                         stream_mode=["custom", "updates"], version="v2"):
    if part["type"] == "custom":
        print("progress", part["data"]["progress"])
    else:
        print("update from", list(part["data"]))
# progress 25 / progress 50 / progress 100 / update from ['research']

