import operator
from typing import Annotated, Literal, TypedDict
from langgraph.graph import StateGraph, START, END
from langgraph.types import Command, Send


class State(TypedDict):
    docs: list[str]
    summaries: Annotated[list[str], operator.add]


def plan(state: State) -> Command[Literal["review"]]:
    return Command(update={"docs": [d.strip() for d in state["docs"]]}, goto="review")


def fan_out(state: State) -> list[Send]:
    return [Send("summarize", {"doc": d}) for d in state["docs"]]   # one task per doc


def summarize(payload: dict) -> dict:
    return {"summaries": [payload["doc"][:10]]}


b = StateGraph(State)
b.add_node(plan)
b.add_node("review", lambda s: {})
b.add_node(summarize)
b.add_edge(START, "plan")
b.add_conditional_edges("review", fan_out, ["summarize"])
b.add_edge("summarize", END)
print(b.compile().invoke({"docs": [" alpha report ", "beta notes"], "summaries": []}))
# {'docs': ['alpha report', 'beta notes'], 'summaries': ['alpha repo', 'beta notes']}

