from typing import TypedDict
from langgraph.checkpoint.memory import InMemorySaver
from langgraph.graph import StateGraph, START, END


class State(TypedDict):
    text: str
    label: str


def classify(state: State) -> dict:
    return {"label": "spam" if "win money" in state["text"] else "ok"}


def create_graph() -> StateGraph:
    b = StateGraph(State)
    b.add_node(classify)
    b.add_edge(START, "classify")
    b.add_edge("classify", END)
    return b


def test_node_directly():
    assert classify({"text": "win money now", "label": ""}) == {"label": "spam"}


def test_whole_graph():
    graph = create_graph().compile(checkpointer=InMemorySaver())
    out = graph.invoke({"text": "hello"}, {"configurable": {"thread_id": "t1"}})
    assert out["label"] == "ok"

from typing import Literal
from langchain_core.messages import AIMessage
from langgraph.graph import StateGraph, START, END, MessagesState
from langgraph.types import Command


class State(MessagesState):
    next_agent: str


def supervisor(state: State) -> Command[Literal["billing", "tech", "__end__"]]:
    last = state["messages"][-1]
    if isinstance(last, AIMessage):                  # a specialist answered: done
        return Command(goto=END)
    text = last.content.lower()                     # real code: model + structured output
    return Command(goto="billing" if "invoice" in text else "tech")


def billing(state: State) -> Command[Literal["supervisor"]]:
    return Command(goto="supervisor", update={"messages": [AIMessage("Billing: invoice resent.")]})


def tech(state: State) -> Command[Literal["supervisor"]]:
    return Command(goto="supervisor", update={"messages": [AIMessage("Tech: try a restart.")]})


b = StateGraph(State)
for fn in (supervisor, billing, tech):
    b.add_node(fn)
b.add_edge(START, "supervisor")
graph = b.compile()
print(graph.invoke({"messages": [{"role": "user", "content": "Where is my invoice?"}]})["messages"][-1].content)
# Billing: invoice resent.

from langgraph.checkpoint.memory import InMemorySaver
from langgraph.func import entrypoint, task
from langgraph.types import Command, interrupt


@task
def write_section(topic: str) -> str:
    return f"A paragraph about {topic}."       # real code: a model call


@entrypoint(checkpointer=InMemorySaver())
def write_report(topics: list[str]) -> str:
    futures = [write_section(t) for t in topics]  # run in parallel
    draft = "\n".join(f.result() for f in futures)
    verdict = interrupt({"review": draft})        # pause for a human
    return draft if verdict == "ok" else "Rejected"


cfg = {"configurable": {"thread_id": "r1"}}
for part in write_report.stream(["bees", "wasps"], cfg):
    print(part)          # ... {'__interrupt__': (Interrupt(value={'review': ...}),)}
print(write_report.invoke(Command(resume="ok"), cfg))
# tasks are not re-run on resume; their saved results are reused

